export interface LogoSvgProps {
  width?: number | string;
  height?: number | string;
  style?: StyleProp<ViewStyle>;
}

export const ExcelLogoSvg: React.FC<LogoSvgProps> = ({ width, height, style }) => {
  const flatStyle = StyleSheet.flatten(style);
  const w = (width ?? flatStyle?.width ?? 150) as number | string;
  const h = (height ?? flatStyle?.height ?? 40) as number | string;
  return (
    <View style={style}>
      <SvgXml xml={EXCEL_LOGO_XML} width={w} height={h} />
    </View>
  );
};

export const SinceLogoSvg: React.FC<LogoSvgProps> = ({ width, height, style }) => {
  const flatStyle = StyleSheet.flatten(style);
  const w = (width ?? flatStyle?.width ?? 38) as number | string;
  const h = (height ?? flatStyle?.height ?? 38) as number | string;
  return (
    <View style={style}>
      <SvgXml xml={SINCE_LOGO_XML} width={w} height={h} />
    </View>
  );
};
